INSERT INTO factor_sources
  (source_code, dataset_name, dataset_version, publisher, geography, source_url, raw_file)
VALUES
  ('CEA','CEA CO2 Baseline Database for the Indian Power Sector','22.0',
INSERT INTO factor_source_policy (category, factory_geography, source, role, rank, rationale) VALUES
  ('electricity','IN','CEA','PRIMARY',1,'CEA v22.0 is the official Indian grid emission factor. The ''Weighted Average Grid Emission Rate (incl. RES, captive)'' series matches what a consumer draws from the grid.'),
  ('electricity','IN','EPA','NOT_APPLICABLE',99,'EPA eGRID factors describe US subregional grids and carry no information about the Indian generation mix.'),
  ('electricity','IN','UK2026','NOT_APPLICABLE',99,'The UK 2026 electricity factor describes the UK grid. The 2026 ''Overseas electricity'' sheet publishes no factors at all, so the UK dataset offers nothing applicable to India.'),
  ('stationary_combustion','IN','CEA','PRIMARY',1,'CEA publishes India-specific fuel emission factors (gCO2/MJ, gross CV basis, oxidation applied) derived from India''s National Communication. Indian coal in particular has a materially different calorific value from US or UK coal.'),
  ('stationary_combustion','IN','UK2026','REFERENCE',2,'UK factors are full CO2e (CO2+CH4+N2O) where CEA is CO2 only, so they are useful as a cross-check and to show the size of the non-CO2 gap, but the fuel specifications are UK ones.'),
  ('stationary_combustion','IN','EPA','REFERENCE',3,'EPA factors are on a US HHV basis with US fuel specifications.'),
  ('mobile_combustion','IN','CEA','PRIMARY',1,'For diesel and other liquid fuels CEA''s India-specific factor applies to on-site mobile plant as much as to stationary combustion.'),
  ('mobile_combustion','IN','UK2026','REFERENCE',2,'UK vehicle factors assume UK fleet composition and fuel blends.'),
  ('mobile_combustion','IN','EPA','REFERENCE',3,'EPA mobile factors assume the US fleet and US fuel specifications.'),
  ('heat_steam','IN','UK2026','REFERENCE',1,'Neither CEA nor EPA publishes a purchased heat/steam factor usable in India; the UK factor is the only available option and is flagged REFERENCE ONLY.'),
  ('heat_steam','IN','CEA','NOT_APPLICABLE',99,'CEA v22.0 publishes grid and power-station fuel factors only. It contains no factor for this activity category.'),
  ('material_use','IN','UK2026','REFERENCE',1,'No Indian cradle-to-gate material dataset is present in the three supplied workbooks. UK 2026 ''Material use'' is the only verified embodied-carbon source available and is flagged REFERENCE ONLY: Indian production routes differ, above all because the Indian grid is roughly five times more carbon intensive than the UK grid.'),
  ('material_use','IN','CEA','NOT_APPLICABLE',99,'CEA v22.0 publishes grid and power-station fuel factors only. It contains no factor for this activity category.'),
  ('waste_disposal','IN','UK2026','REFERENCE',1,'No Indian waste treatment factors exist in the supplied datasets. UK 2026 ''Waste disposal'' is used and flagged REFERENCE ONLY; landfill methane capture rates in particular differ between the UK and India.'),
  ('waste_disposal','IN','CEA','NOT_APPLICABLE',99,'CEA v22.0 publishes grid and power-station fuel factors only. It contains no factor for this activity category.'),
  ('freight_transport','IN','UK2026','REFERENCE',1,'UK freight factors assume UK vehicle classes and load factors; flagged REFERENCE ONLY.'),
  ('freight_transport','IN','CEA','NOT_APPLICABLE',99,'CEA v22.0 publishes grid and power-station fuel factors only. It contains no factor for this activity category.'),
  ('business_travel','IN','UK2026','REFERENCE',1,'UK travel factors assume UK fleet and rail mix; flagged REFERENCE ONLY.'),
  ('business_travel','IN','CEA','NOT_APPLICABLE',99,'CEA v22.0 publishes grid and power-station fuel factors only. It contains no factor for this activity category.'),
  ('water','IN','UK2026','REFERENCE',1,'UK water supply and treatment factors reflect UK utilities; flagged REFERENCE ONLY.'),
  ('water','IN','CEA','NOT_APPLICABLE',99,'CEA v22.0 publishes grid and power-station fuel factors only. It contains no factor for this activity category.'),
  ('refrigerant','IN','UK2026','REFERENCE',1,'Refrigerant GWPs are IPCC values and are close to geography-independent, but the UK sheet''s leakage assumptions are UK ones.'),
  ('refrigerant','IN','CEA','NOT_APPLICABLE',99,'CEA v22.0 publishes grid and power-station fuel factors only. It contains no factor for this activity category.'),
  ('wtt_upstream','IN','UK2026','REFERENCE',1,'Well-to-tank factors depend on national fuel supply chains; the UK values are flagged REFERENCE ONLY.'),
  ('wtt_upstream','IN','CEA','NOT_APPLICABLE',99,'CEA v22.0 publishes grid and power-station fuel factors only. It contains no factor for this activity category.'),
  ('transmission_distribution','IN','UK2026','REFERENCE',1,'UK T&D loss factors reflect the UK network. India''s T&D losses are substantially higher, so this is REFERENCE ONLY and is better replaced by a CEA/utility loss figure.'),
  ('transmission_distribution','IN','CEA','NOT_APPLICABLE',99,'CEA v22.0 publishes grid and power-station fuel factors only. It contains no factor for this activity category.'),
  ('outside_scopes','IN','UK2026','REFERENCE',1,'Outside-of-scopes reporting items from the UK dataset.'),
  ('outside_scopes','IN','CEA','NOT_APPLICABLE',99,'CEA v22.0 publishes grid and power-station fuel factors only. It contains no factor for this activity category.'),
  ('waste_disposal','IN','EPA','REFERENCE',2,'EPA publishes a factor for this category, but on US assumptions; kept as a second reference so the two can be compared in Evidence.'),
